const settings = $('Settings').first().json;
const alertWhenClean = settings.alertWhenClean === true;
const all = $input.all().map((item) => item.json);

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hasVersioning = all.some(
  (w) => Object.prototype.hasOwnProperty.call(w, 'activeVersion') ||
    Object.prototype.hasOwnProperty.call(w, 'activeVersionId'));
const isLive = (w) => (hasVersioning ? Boolean(w.activeVersion || w.activeVersionId) : w.active === true);
const byId = new Map(all.map((w) => [String(w.id), w]));
const groups = new Map();
const add = (key, reason, handler, producer) => {
  if (!groups.has(key)) groups.set(key, { reason, handler, affected: [] });
  groups.get(key).affected.push(producer);
};
let checked = 0;
for (const w of all) {
  if (w.isArchived || !isLive(w)) continue;
  const ref = w.settings && w.settings.errorWorkflow;
  if (!ref) continue;
  checked++;
  const h = byId.get(String(ref));
  if (!h) { add('missing:' + ref, 'missing', String(ref), w.name); continue; }
  if (!isLive(h)) { add('unpublished:' + h.id, 'unpublished', h.name, w.name); continue; }
  const nodes = Array.isArray(h.nodes) ? h.nodes : [];
  if (!nodes.some((n) => n.type === 'n8n-nodes-base.errorTrigger')) {
    add('no_error_trigger:' + h.id, 'no_error_trigger', h.name, w.name);
  }
}
const problems = [...groups.values()];
const shouldPost = problems.length > 0 || alertWhenClean === true;
const why = {
  unpublished: 'It has no published version, so n8n skips it and writes one line to the server log.',
  missing: 'The workflow set as the error workflow no longer exists.',
  no_error_trigger: 'It has no Error Trigger node, so n8n has nothing to start it with.',
};
let text;
if (problems.length === 0) {
  text = '<b>n8n error routing check</b>\n\nAll clear. ' + checked +
    ' published workflow(s) route errors to a handler that is published and has an Error Trigger.';
} else {
  const L = ['<b>n8n error routing check</b>', '',
    problems.length + ' broken route(s). ' + checked + ' published workflow(s) checked.'];
  for (const p of problems) {
    L.push('', '<b>' + esc(p.handler) + '</b>', why[p.reason],
      'Failures from ' + p.affected.length + ' workflow(s) go unreported:');
    for (const n of p.affected.slice(0, 15)) L.push('  • ' + esc(n));
    if (p.affected.length > 15) L.push('  … and ' + (p.affected.length - 15) + ' more');
  }
  text = L.join('\n');
}
return [{ json: { shouldPost, problemCount: problems.length, checked, problems, text } }];
